do $$ begin if current_database() !~ '^dorm_repair_v2_(dev|test(_[a-z0-9]+)?)$' then raise exception 'Unsafe target'; end if; end $$;
select guard_key from public.system_guard where guard_key='rbac-admin' for update;
create temporary table c_custodians on commit drop as select u.id from public.sys_user u where u.enabled and not exists(select 1 from public.sys_permission p where p.available and not exists(select 1 from public.sys_user_role ur join public.sys_role r on r.id=ur.role_id and r.enabled join public.sys_role_permission rp on rp.role_id=r.id where ur.user_id=u.id and rp.permission_id=p.id));
alter table public.sys_permission drop constraint sys_permission_module_check;
alter table public.sys_permission add constraint sys_permission_module_check check(module in ('V2_IDENTITY','V1_BRIDGE','V2_FOUNDATION'));
insert into public.sys_permission(code,description,module) values ('category:read','选择有效分类与项目','V2_FOUNDATION'),('category:write','管理故障分类与项目','V2_FOUNDATION'),('space:read','选择有效校园位置','V2_FOUNDATION'),('space:write','管理校园空间','V2_FOUNDATION'),('facility:read','查询设施预填信息','V2_FOUNDATION'),('facility:write','管理完整设施档案','V2_FOUNDATION');
create temporary table c_changed_users on commit drop as select distinct ur.user_id from public.sys_user_role ur where exists(select 1 from public.sys_role_permission rp join public.sys_permission p on p.id=rp.permission_id where rp.role_id=ur.role_id and p.code in ('category:read','category:write','space:read','space:write','facility:read','facility:write'));
insert into public.sys_role_permission(role_id,permission_id) select distinct ur.role_id,p.id from c_custodians c join public.sys_user_role ur on ur.user_id=c.id join public.sys_role r on r.id=ur.role_id and r.enabled cross join public.sys_permission p where p.module='V2_FOUNDATION' on conflict do nothing;
-- Seed templates only when no users exist; active-user grants above are permission-derived.
insert into public.sys_role_permission(role_id,permission_id) select r.id,p.id from public.sys_role r cross join public.sys_permission p where p.module='V2_FOUNDATION' and not exists(select 1 from public.sys_user) and (r.code='ADMIN' or (r.code in ('STUDENT','REPAIRER') and p.code in ('category:read','space:read','facility:read'))) on conflict do nothing;
-- Existing fixed-role users receive selection capabilities only through already-owned legacy capabilities.
insert into public.sys_role_permission(role_id,permission_id) select distinct rp.role_id,p.id from public.sys_role_permission rp join public.sys_permission old on old.id=rp.permission_id cross join public.sys_permission p where old.code in ('legacy:student','legacy:repairer') and p.code in ('category:read','space:read','facility:read') on conflict do nothing;
update public.sys_user set auth_version=auth_version+1,version=version+1 where id in(select distinct ur.user_id from public.sys_user_role ur join public.sys_role_permission rp on rp.role_id=ur.role_id join public.sys_permission p on p.id=rp.permission_id where p.module='V2_FOUNDATION');
update public.sys_role set version=version+1 where id in(select rp.role_id from public.sys_role_permission rp join public.sys_permission p on p.id=rp.permission_id where p.module='V2_FOUNDATION');
insert into public.system_guard(guard_key) values ('foundation-catalog');
create table public.campus (id bigint generated by default as identity primary key, code varchar(50) not null unique, name varchar(100) not null, enabled boolean not null default true, sort_order integer not null default 0 check(sort_order>=0), version integer not null default 0 check(version>=0), created_at timestamptz not null default current_timestamp);
create table public.building (id bigint generated by default as identity primary key, code varchar(50) not null unique, name varchar(100) not null, enabled boolean not null default true, sort_order integer not null default 0 check(sort_order>=0), version integer not null default 0 check(version>=0), created_at timestamptz not null default current_timestamp,campus_id bigint not null references public.campus(id) on delete restrict,unique(campus_id,name));
create table public.building_floor(id bigint generated by default as identity primary key,building_id bigint not null references public.building(id) on delete restrict,floor_no integer not null check(floor_no between -20 and 200),name varchar(100) not null,enabled boolean not null default true,sort_order integer not null default 0 check(sort_order>=0),version integer not null default 0 check(version>=0),unique(building_id,floor_no),unique(building_id,name),unique(id,building_id));
create table public.room(id bigint generated by default as identity primary key,floor_id bigint not null references public.building_floor(id) on delete restrict,room_no varchar(40) not null,name varchar(100) not null,kind varchar(10) not null check(kind in ('PRIVATE','PUBLIC')),enabled boolean not null default true,sort_order integer not null default 0 check(sort_order>=0),version integer not null default 0 check(version>=0),unique(floor_id,room_no),unique(floor_id,name),unique(id,floor_id));
create table public.repair_category(id bigint generated by default as identity primary key, code varchar(50) not null unique, name varchar(100) not null, enabled boolean not null default true, sort_order integer not null default 0 check(sort_order>=0), version integer not null default 0 check(version>=0), created_at timestamptz not null default current_timestamp,parent_id bigint references public.repair_category(id) on delete restrict,check(parent_id is null or parent_id<>id));
create index ix_category_parent on public.repair_category(parent_id,sort_order,id);
create table public.repair_item(id bigint generated by default as identity primary key, code varchar(50) not null unique, name varchar(100) not null, enabled boolean not null default true, sort_order integer not null default 0 check(sort_order>=0), version integer not null default 0 check(version>=0), created_at timestamptz not null default current_timestamp,category_id bigint not null references public.repair_category(id) on delete restrict,estimated_minutes integer not null check(estimated_minutes between 1 and 1440),is_quick boolean not null default false,unique(category_id,name));
create index ix_item_category on public.repair_item(category_id,sort_order,id);
create table public.facility_type(id bigint generated by default as identity primary key, code varchar(50) not null unique, name varchar(100) not null, enabled boolean not null default true, sort_order integer not null default 0 check(sort_order>=0), version integer not null default 0 check(version>=0), created_at timestamptz not null default current_timestamp);
create table public.facility_type_repair_item(type_id bigint not null references public.facility_type(id) on delete restrict,item_id bigint not null references public.repair_item(id) on delete restrict,primary key(type_id,item_id));
create index ix_type_item_reverse on public.facility_type_repair_item(item_id,type_id);
create table public.facility(id bigint generated by default as identity primary key,asset_no varchar(60) not null unique,name varchar(100) not null,facility_type_id bigint not null references public.facility_type(id) on delete restrict,building_id bigint not null references public.building(id) on delete restrict,floor_id bigint,room_id bigint,public_zone varchar(150),status varchar(20) not null check(status in ('ACTIVE','MAINTENANCE','DISABLED')),version integer not null default 0 check(version>=0),qr_token varchar(64) not null unique,qr_token_hash varchar(64) not null unique,created_at timestamptz not null default current_timestamp,foreign key(floor_id,building_id) references public.building_floor(id,building_id) on delete restrict,foreign key(room_id,floor_id) references public.room(id,floor_id) on delete restrict,check(room_id is null or floor_id is not null),check((room_id is not null and public_zone is null) or (room_id is null and public_zone is not null and length(trim(public_zone))>0)));
create index ix_facility_location on public.facility(building_id,floor_id,room_id,status,id);
create index ix_facility_type on public.facility(facility_type_id,id);
insert into public.repair_category(code,name,sort_order) values ('WATER','水',1),('WOOD','木',2),('MASONRY','泥',3),('PAINT','漆',4),('DRAIN','下水',5),('OTHER','其他',6),('AC','空调',7),('ELECTRIC','电',8);
create function public.check_category_tree() returns trigger language plpgsql as $$ declare depth integer; cycle boolean; begin
 perform guard_key from public.system_guard where guard_key='foundation-catalog' for update;
 if tg_op='UPDATE' and old.parent_id is null and new.parent_id is distinct from old.parent_id then raise exception 'Root cannot move' using errcode='23514'; end if;
 if tg_op='INSERT' and new.parent_id is null and (select count(*) from public.repair_category where parent_id is null)>=8 then raise exception 'Exactly eight roots' using errcode='23514'; end if;
 with recursive ancestors(id,parent_id,path) as(select id,parent_id,array[id] from public.repair_category where id=new.parent_id union all select c.id,c.parent_id,a.path||c.id from public.repair_category c join ancestors a on c.id=a.parent_id where not c.id=any(a.path)) select count(*),coalesce(bool_or(id=new.id),false) into depth,cycle from ancestors;
 if cycle or depth>=3 then raise exception 'Invalid category ancestry' using errcode='23514'; end if;
 if tg_op='UPDATE' then
 with recursive descendants(id,d) as(select new.id,1 union all select c.id,d.d+1 from public.repair_category c join descendants d on c.parent_id=d.id where c.id<>new.id) select max(d) into depth from descendants;
 if depth+(with recursive a(id,parent_id) as(select id,parent_id from public.repair_category where id=new.parent_id union all select c.id,c.parent_id from public.repair_category c join a on c.id=a.parent_id) select count(*) from a)>3 then raise exception 'Subtree too deep' using errcode='23514'; end if; end if;
 return new; end $$;
create trigger category_tree_guard before insert or update on public.repair_category for each row execute function public.check_category_tree();
